n=23
G=[]
for r in range(n):
 if r==0: G.append([((c+1)%9)+1 for c in range(n)])
 else:
  base=[((c+2)%9)+1 for c in range(n-1)]
  G.append(base[:r+1]+base[r:])
import json
print(json.dumps(G,separators=(',',':')))

